INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('splugorth', 'Splugorth', 'alien', 'rifts', 0, 'Any, but usually Anarchist or evil', '{"IQ":"3D6+12","ME":"4D6+12","MA":"3D6+12","PS":"5D6+28","PP":"3D6+12","PE":"3D6+12","PB":"1D6","Spd":"1D6x10"}', NULL, NULL, '3D4x10000', '6D4x1000', '1D6x1000', 'M.D.C. is spread by location the way Splynncryth''s is (giant eye, eye film, eye spines, tentacles, main body). A main body at zero is impaired rather than destroyed (Splynncryth''s block puts destruction at negative 4000). Living away from any P.P.E. source it keeps a quarter of its M.D.C., P.P.E. and I.S.P. Average level 2D4+5.', NULL, 17, '{"initiative":6,"strike":2,"parry":2,"dodge":-2}', 'One physical attack per melee for each tentacle (2D4+5), half as many psionic attacks, or two by magic. Bonuses as Splynncryth: minus 2 to dodge, +6 vs Horror Factor, +2 on all saves, immune to mind control. Critical strike on 18-20. Silver and magic weapons do triple damage. Its damage follows its P.S.; no damage table is printed for the species. Away from P.P.E. it has half its bonuses and two fewer physical attacks.', 'Leaves ordinary skills to minions. Dragonese/Elf, Faerie, Gobblely, American, Euro and Atlantean at 98%, and magic for any other tongue; intelligence, swimming, climbing, palming, basic and advanced math and land navigation 98%; pick pockets, demon and faerie lore and writing 71%; magic lores (tattoos, runes, symbols, circles, wards, enchantment, magic items) 90%.', 'As Splynncryth: nightvision 1000 ft, superior color vision, sees the invisible, bio-regenerates 2D6x10 M.D.C. a minute and regrows limbs in 72 hours, needs no air; dimensional teleport 98% to any world it rules and can open a rift to anywhere it has been; teleports 600 miles; possession; turns, animates and controls up to 600 dead; healing touch 1D6x10, restoration, resurrection, stone to flesh, remove curse; summons 2D6 High Lords or 6D6 lesser minions three times a day. Can split its essence into 4D4 fragments that possess hosts on other worlds.', 'All ley line walker spells and rituals, stone master powers, the making of magic tattoos and rune weapons, and one more field: bio-wizardry, shifter/summoner or diabolism (never mystic, warlock, witch or techno-wizard magic).', 'All sensitive, healing and super psionic powers, at level 2D4+5.', 'About 25 ft (7.6 m) across and 12 ft (3.6 m) tall; tentacles about 50 ft (15 m) long', '20 to 50 tons', '5D4x10,000 years', 'Atlantis and the other worlds of the Splugorth empire', 'Their minions: High Lords, Kydians, Kittani, Metztla, the Sunaj and many more', 'True Atlanteans and vampires, old foes', 'Not available as a player character, as the book stresses. Special NPC R.C.C.: ley line walker, rune master, stone master, tattoo master and shifter/summoner.', 'Alien intelligences of vast age: a slimy flesh mound crowned by one great spine-ringed eye, with 2D4+5 tentacles, four of them toothed mouths. They feed on P.P.E. and flesh, rule empires of enslaved races through their minions, and prize bio-wizardry and rune magic.', 'Rifts World Book 2: Atlantis p.41'),
('splugorth-high-lord', 'Splugorth High Lord', 'alien humanoid', 'rifts', 0, 'Any, but usually Aberrant, Miscreant or Diabolic', '{"IQ":"3D6+6","ME":"3D6+6","MA":"3D6","PS":"4D6+6","PP":"3D6+6","PE":"3D6+6","PB":"1D6","Spd":"3D6+6"}', NULL, NULL, '1D4x100', '1D4x100+100', '2D4x10', 'M.D.C. comes from the link to their Splugorth; without it they would be S.D.C. beings. Half the P.P.E. is drawn from the Splugorth. P.S. is supernatural. Standard High Lord armor adds 100 M.D.C. Average level 8th (2D4+2 for a random level; seldom above 10th).', NULL, 14, '{"attacks":5,"strike":1,"parry":1,"dodge":1,"roll":2,"pull":2}', 'Five physical attacks or two by magic. +1 to strike with a body block. +1 to save vs psionics, +1 vs magic, +6 vs Horror Factor. Critical strike on 19-20. Like a psi-stalker, it lives on P.P.E. taken from living beings.', 'Biology (-40% on non-human aliens), astronomy, chemistry, analytical chemistry, pathology, holistic medicine, basic and advanced math, computer operation, radio: basic and scrambler, all 98%; seven languages including Spanish and Atlantean at 98%; intelligence 98%, forgery and escape artist 68%, swimming and SCUBA 98%; W.P. knife, energy pistol and energy rifle (plus sword for a rune master). Tattoo magic, mystic symbols, circles and wards 98%, recognize enchantment 65%, magic items 50% (98% for a rune master).', 'Through the Splugorth link: nightvision 1000 ft, excellent color vision, turns invisible at will, sees the invisible, bio-regenerates 1D4x10 M.D.C. a minute, and can dimensionally teleport (98%) to its master once a day. Cannot bear magic tattoos itself.', 'Every spell and ritual of levels 1-13, all stone master powers, the making of magic tattoos, and one more field: techno-wizard, bio-wizard, stone master or shifter/summoner. Under 2% become rune masters, who read runes, command rune statues and are given rune weapons.', 'Major psionic: astral projection, empathy, mind block, object read, sense magic, speed reading, telepathy, total recall.', '6 to 7 ft (1.8 to 2.1 m)', '150 to 200 lbs (67.5 to 90 kg)', '1200+ years', 'Wherever the Splugorth rule; hundreds of thousands for every Splugorth', 'Their Splugorth masters, served with total loyalty; often keep a T-Man slave or two', NULL, 'Not available as a player character. Special magic R.C.C.: 8th level ley line walker, 8th level tattoo maker and 8th level in one more field of magic. Carries one bio-wizard weapon and 1D4 other bio-wizard devices.', 'Tall, gaunt, grey-skinned humanoids with huge toothy mouths and insect-black eyes who serve the Splugorth as priests, sorcerers, alchemists, governors and generals. They draw part of their power from their master and may be a kind of P.P.E. symbiote.', 'Rifts World Book 2: Atlantis p.43-45'),
('splugorth-slaver', 'Splugorth Slaver', 'monster', 'rifts', 0, 'Miscreant or Diabolic only', '{"IQ":"10","ME":"25","MA":"6","PS":"28","PP":"19","PE":"23","PB":"4","Spd":"22"}', '2D6x10', NULL, '120', '4D6x10', '1D6x10', 'Attributes are printed as typical fixed figures; Spd 22 does not apply to a Slaver bonded to its barge. S.D.C. does not apply. The 120 M.D.C. is an Armor of Ithan that springs up at any threat and renews one melee round after it is destroyed; the barge and its eyes add their own.', NULL, 16, '{"attacks":10,"initiative":6,"strike":4,"parry":10,"dodge":4}', 'Cannot be surprised or attacked from behind. +5 to save vs Horror Factor, +5 vs psionics, +4 vs magic and poison, +16% vs coma/death. Tentacle reach 16 ft (5 m). A Slaver not bonded to a barge has 5 attacks, half the bonuses and no magic.', NULL, 'Sees through the barge''s five eyes, five floating eyes and its staff of Eylor all at once, and needs little sleep. Swims 98%, holds its breath 6D6 minutes, smells blood up to 4000 ft (1200 m), tracks by blood scent 66% and knows human blood 66%; eats only meat, preferably human.', 'Only what the barge, the eyes and the staff of Eylor give it.', 'Mind block and telepathy.', '10 to 12 ft (3 to 3.6 m) tall in the barge; about 20 ft (6 m) long with its snake-like lower body when unbonded', NULL, NULL, 'Atlantis; the only minions who raid beyond the continent for slaves', 'Four to six blind warrior women ride with each barge', NULL, 'Not available as a player character. Carries bio-wizard microbes, mind slugs, twenty zombitrons, mystic leeches, a pathic healer and a telepathic holographic imager on the barge.', 'The eyeless, multi-tentacled slave raider fused into its Eylor barge, often taken outside Atlantis for the Splugorth itself and nicknamed Sploog in Europe. A natural predator with a taste for humanoid blood.', 'Rifts World Book 2: Atlantis p.49-50'),
('murex-metztla', 'Murex Metztla', 'alien', 'rifts', 0, 'Any, but almost always Diabolic or Miscreant', '{"IQ":"3D6+6","ME":"24","MA":"2D6","PS":"40","PP":"24","PE":"30","PB":"1D6","Spd":"2D4"}', NULL, NULL, '5000', '1D6x10', '1D4x100', 'M.D.C. by location: tentacles (12) 75 each, mouth 300, sensor lobe 1000, eyes (2) 100 each, forward cannons (2) 150 each, main body 5000 (stored). P.S. and P.P. are those of the tentacles. Spd is crawling; swims 2D4x10 and flies 2D4x10. I.S.P. +20 per level. Typically 6th level, sometimes up to 9th.', NULL, 17, '{"attacks":12,"initiative":2,"strike":6,"parry":10,"dodge":2,"roll":2,"pull":6}', 'Twelve physical or six psionic attacks, or three psionic and four physical. The printed bonuses include everything. +4 to strike with a body ram. +6 vs Horror Factor, +5 vs psionics, +8 vs magic and poison. Critical strike on 19-20. Blinded, it loses only 1 from each combat bonus.', 'Basic and advanced math, astronomy, biology, botany, demon and monster lore, land and underwater navigation and wilderness survival, all +20%; Dragonese and 1D4 other languages.', 'Twelve barbed 20 ft prehensile tentacles that regrow in 2D4 days and can pin and crush; amplified hearing, sonar, motion detection and keen smell (tracks blood and decay 85% out to two miles, twice that underwater); poor sight above water (about 500 ft) but sharp below; flies and swims 98%; breathes air or water; blends in like an octopus underwater (prowl 90%) when still or slow.', 'P.P.E. only; does not study magic, but hoards and uses magic weapons and items.', 'Master psionic: resist fatigue, hunger and thirst, impervious to cold, levitation, death trance, presence sense, telepathy, total recall, astral projection, telekinesis, hydrokinesis, electrokinesis, mind bolt, P.P.E. shield, mind block auto-defense.', '20 to 30 ft (6 to 9 m) tall, about 50 ft (15.2 m) long', '40 tons', '5000 years', 'Metztla hives; prefers land close to water it can hide and sleep in', 'Other Metztla and their drones; sometimes the Minions of Splugorth', NULL, 'Not available as a player character. 10% of the Metztla are Murex.', 'A shelled, tentacled leader caste of the hive-like Metztla, as cruel as any demon though not supernatural. It leads drones and lesser Metztla, attacks humans and D-Bees unprovoked, and stirs up weaker evil beings for sport.', 'Rifts World Book 2: Atlantis p.54-56'),
('volute-metztla', 'Volute Metztla', 'alien', 'rifts', 0, 'Any, but almost always Diabolic or Miscreant', '{"IQ":"3D6+8","ME":"28","MA":"2D6","PS":"50","PP":"24","PE":"30","PB":"1D6","Spd":"3D6+24"}', NULL, NULL, '4200', '1D4x10', '1D4x100+100', 'M.D.C. by location: finger-like appendages (6) 200 each, sensor lobe 700, eyes (6) 100 each, stingers (4) 100 each, main body 4200 (stored). P.S. and P.P. are those of its legs and fingers. Spd is crawling; swims 3D4x10 and flies 1D4x10+12. I.S.P. +20 per level. Typically 7th level, sometimes up to 10th.', NULL, 18, '{"attacks":8,"initiative":4,"strike":7,"parry":8,"dodge":4,"roll":2,"pull":4}', 'Eight physical or six psionic attacks, or three psionic and two physical. The printed bonuses include everything. +2 to strike with a body ram. +6 vs Horror Factor, +7 vs psionics, +8 vs magic and poison. Critical strike on 19-20. Six eyes see every way, so it cannot be surprised; blinded, it loses 2 from each combat bonus.', 'Basic and advanced math, astronomy, biology, botany, demon and monster lore, land and underwater navigation and wilderness survival, all +20%; Dragonese and 1D4+1 other languages.', 'Six spiked 15 ft appendages serve as legs and fingers (regrow in 3D4 days) and climb 60% (+15% underwater); senses as the Murex, tracking blood and decay 80%; sight about human and sharper underwater; eyes regrow in 1D4 weeks; flies and swims 98%; breathes air or water; octopus-like camouflage underwater (prowl 80%).', 'P.P.E. only; no magic power or knowledge.', 'The strongest Metztla psychic: healing touch, deaden pain, psychic diagnosis, detect psionics, sense magic, see aura, see the invisible, presence sense, telepathy, total recall, astral projection, ectoplasm, super telekinesis, telekinetic force field, bio-manipulation, empathic transmission, mind bolt, group mind block, mind block auto-defense.', '20 to 30 ft (6 to 9 m) tall, about 10 ft (3 m) wide', '40 tons', '6000 years', 'Metztla hives, near water', 'Other Metztla and their drones', NULL, 'Not available as a player character. Never uses a man-made weapon. 6% of the Metztla are Volute.', 'The other leader caste of the Metztla: a knobbed, many-eyed mass on six finger-legs with a beak-like stabbing mouth and four paralysing stingers. Deadlier than the Murex at close quarters.', 'Rifts World Book 2: Atlantis p.56-57'),
('murvolva-metztla', 'Murvolva Metztla', 'alien', 'rifts', 0, 'Any, but almost always Diabolic or Miscreant', '{"IQ":"3D6","ME":"21","MA":"2D6","PS":"20","PP":"20","PE":"24","PB":"1D6","Spd":"2D4"}', NULL, NULL, '1000', '1D4x10', '2D6x10', 'M.D.C. by location: retractable tentacles (2) 30 each, sensor lobe 500, eyes (9) 25 each, forward cannons (2) 100 each, bony fins (2) 150 each, bony spine 300, main body 1000 (stored). P.S. and P.P. are those of the tentacles. Spd is crawling; swims 2D6x10 and flies 4D4x10. I.S.P. +10 per level. Typically 5th level, sometimes up to 7th.', NULL, 14, '{"attacks":6,"initiative":3,"strike":6,"parry":3,"dodge":5,"roll":2,"pull":2}', 'Six physical or energy attacks, four psionic, or two of each. The printed bonuses include everything. +2 to strike with a body ram. +6 vs Horror Factor, +2 vs psionics, +5 vs magic and poison. Critical strike only on a natural 20. Blinded, it loses 2 from each combat bonus.', 'Basic math, astronomy, demon and monster lore, land and underwater navigation, tracking of humans and animals and wilderness survival, all +20%; Dragonese and 1D4 other languages.', 'Two retractable 10 ft tentacles (regrow in 2D4 days) that can pin and crush; senses as the Murex, tracking blood and decay 90%; sight a little better than human, sharper underwater and with infrared; flies and swims 98%; breathes air or water; prowl 50%, 90% when still underwater.', 'P.P.E. only; does not study magic, but likes to collect and use magic items.', 'Master psionic: resist fatigue, see the invisible, see aura, nightvision, impervious to cold, levitation, death trance, presence sense, telepathy, telekinesis, hydrokinesis, mind bolt, mind block auto-defense.', '8 to 12 ft (2.4 to 3.6 m) tall, about 10 ft (3 m) long', 'Two tons', '3000 years', 'Metztla hives; travels in groups of two to six', 'Its larger Metztla brothers; commands 1D6+1 Kree-Carapace drones', NULL, 'Not available as a player character. 22% of the Metztla are Murvolva.', 'A small, stubby, shelled Metztla that hunts, scavenges and spies for its elders and loves to chase and torment weaker creatures.', 'Rifts World Book 2: Atlantis p.57-58'),
('kreelong-carapace', 'Kreelong Carapace', 'alien', 'rifts', 0, 'Any, but almost always Aberrant or Miscreant', '{"IQ":"1D6+4","ME":"22","MA":"2D6","PS":"40","PP":"24","PE":"26","PB":"1D6","Spd":"6D6+4"}', NULL, NULL, '3400', '1D4x10', '3D4x10', 'M.D.C. by location: finger stalks (2) 80 each, main mouth 300, large feelers (2) 50 each, centipede tentacle 150, tail 200, electro-cannon spines (11) 10 each, sensor lobe 1000, segmented eyes (11) 100 each, forelegs (2) 150 each, hind legs (2) 300 each, main body 3400 (stored). Spd is running and climbing; swims 1D4x10; cannot fly. I.S.P. +10 per level. Typically 6th level, sometimes up to 9th.', NULL, 16, '{"attacks":6,"initiative":1,"strike":4,"parry":4,"roll":2,"pull":2}', 'Six hand to hand or four psionic attacks; its eleven spines fire as many blasts as it has hand to hand attacks. The printed bonuses include everything; no dodge bonus is printed. +2 to strike with a body ram. +6 vs Horror Factor, +4 vs psionics, +6 vs magic and poison. Critical strike on 19-20.', 'Basic math, land and underwater navigation and wilderness survival, all +10%; understands Dragonese, Gobblely and Metztla at 90%.', 'Climbs 85%, digs and tunnels 90%, builds 85%, swims 80%, prowl 20%; secretes a concrete-like building resin; amplified hearing, heightened taste and touch, sonar, motion detection and fair smell (tracks blood and decay 55%); poor insect-like sight from eleven eyes; breathes air or water.', 'P.P.E. only; cannot learn magic.', 'Master psionic: resist fatigue, hunger and thirst, impervious to cold, presence sense, telepathy, super telekinesis.', '12 to 20 ft (3.6 to 6 m) tall, about 50 ft (15.2 m) long', '34 tons', '4000 years', 'The Metztla hive, which it leaves only when ordered', 'Obeys the queen and the superior Metztla', NULL, 'Not available as a player character. 24% of the Metztla are Kreelong.', 'The dull-witted worker drone of the Metztla, a huge shelled thing of feelers, finger-stalks and a centipede-like grasping tentacle that digs, hauls and builds the hive, and fights with claws, tail and eleven small electrical spines.', 'Rifts World Book 2: Atlantis p.60-61'),
('kreewarr-carapace', 'Kreewarr Carapace', 'alien', 'rifts', 0, 'Any, but almost always Aberrant or Miscreant', '{"IQ":"1D6+4","ME":"22","MA":"2D6","PS":"60","PP":"24","PE":"26","PB":"1D6","Spd":"4D6+6"}', NULL, NULL, '5600', '1D4x10', '4D4x10', 'M.D.C. by location: head (with the sensor lobe) 1000, mouth 400, forearm pincers (2) 300 each, forelegs (2) 450 each, hind legs (8) 200 each, cannon 300, tail 350, top fin plates (2) 350 each, main body 5600 (stored). Spd is running and climbing; swims 1D4x10; cannot fly. I.S.P. +10 per level. Typically 5th level, sometimes up to 7th.', NULL, 17, '{"attacks":7,"initiative":4,"strike":6,"parry":6,"roll":2,"pull":3}', 'Seven hand to hand or four psionic attacks. The printed bonuses include everything; no dodge bonus is printed. +2 to strike with a body ram. +6 vs Horror Factor, +4 vs psionics, +6 vs magic and poison. Critical strike on 18-20. The tail cannot power strike. Pincers regrow in 1D4 weeks, legs in 1D6, the cannon in 4D4.', 'Basic math, demon and monster lore, land and underwater navigation and wilderness survival, all +10%; understands Dragonese/Elf, Gobblely and Metztla at 90%.', 'Blind; relies on amplified hearing, heightened taste and touch, radar and sonar, motion detection, very keen smell (tracks blood and decay 92% out to two miles) and psionics. Climbs 55%, digs 50%, builds 45%, swims 75%, prowl 40%; breathes air or water; the Metztla are immune to its irritant mist.', 'P.P.E. only; cannot learn magic.', 'Master psionic: resist fatigue, hunger and thirst, impervious to cold, see the invisible, sense evil, sense magic, sixth sense, presence sense, telepathy, bio-regeneration, super telekinesis.', '20 to 26 ft (6 to 7.9 m) tall, about 45 ft (13.7 m) long', '52 tons', '4000 years', 'The Metztla hive', 'Obeys the queen and the superior Metztla', NULL, 'Not available as a player character. 20% of the Metztla are Kreewarr.', 'The soldier drone of the Metztla: a blind, crab-like colossus with pincers, clawed forelegs, a scissoring tail and a cannon-like protrusion, which fights to the death for its queen and hive.', 'Rifts World Book 2: Atlantis p.61-63'),
('dragonsaurus', 'Dragonsaurus', 'animal', 'rifts', 0, 'Generally Unprincipled or Anarchist', '{"IQ":"1D6","ME":"3D6+6","MA":"3D6+6","PS":"3D6+10","PP":"4D6","PE":"4D6","PB":"3D6+6","Spd":"6D6"}', NULL, NULL, '6D6+34', '6D6', NULL, 'I.Q. is animal intelligence, about a German shepherd''s.', NULL, 10, '{"attacks":6,"initiative":2,"strike":3,"parry":2,"dodge":2,"roll":3}', 'Four physical attacks plus two with its prehensile tail. +4 vs Horror Factor, +2 on all saves. Often mistaken for a baby dragon.', NULL, 'Nightvision 200 ft, superior hearing, keen color vision, tracks by smell 75%, prowl 45%, swims 80%, climbs 80%; leaps 60 ft long or 30 ft high from a standstill.', 'None', 'None', '6 to 10 ft (1.8 to 3 m) long, about 4 ft (1.2 m) tall; females about 15% smaller', '350 to 500 lbs (157 to 225 kg)', '60 years', 'Sold in Atlantis, where it is as common as dogs and cats once were; escaped pets live wild in America, Africa and Atlantis', NULL, 'Larger predators', 'Optional pet or guard animal. Slave market: 20,000 credits untamed, 40,000 trained, up to 50% more near maximum M.D.C.', 'A small, wingless, dragon-like reptile in shades of green with a dog''s intelligence and no magic, the favorite pet, guard and hunting animal of the dragon-revering minions. Lays 1D6 eggs a year.', 'Rifts World Book 2: Atlantis p.70-71'),
('yll-tree-climber', 'Yll Tree Climber', 'animal', 'rifts', 0, 'Generally Unprincipled or Anarchist', '{"IQ":"1D6+2","ME":"3D6+4","MA":"3D6+4","PS":"4D6+10","PP":"3D6+10","PE":"3D6+10","PB":"3D6","Spd":"2D4x10"}', NULL, NULL, '1D4x100+60', '5D6', NULL, 'M.D.C. by location: head 150, forearms (2) 75 each, hind legs (2) 110 each, spiny tail 130, protective plates (5) 150 each, main body 1D4x100+60 (stored). Spd triples among giant trees and doubles climbing mountains. I.Q. is animal, about a chimpanzee''s. The section heading prints the name Yil-Tree Climber; the stat block prints Yll.', NULL, 11, '{"attacks":6,"initiative":3,"strike":2,"parry":2,"dodge":2,"roll":6}', 'Four physical attacks plus two with the tail. +3 to strike pouncing from above. +2 vs Horror Factor, +1 vs magic and poison.', NULL, 'Nightvision 60 ft, superior hearing, keen color vision, tracks by smell 55%, prowl 42%, swims 80%, climbs 94%, acrobatics 94%; leaps 60 ft long or 30 ft high; climbs wood, stone and concrete with ease.', 'None', 'None', '8 to 11 ft (2.4 to 3.3 m) long; about 5 ft (1.5 m) tall on all fours, 10 ft (3 m) upright; females about 10% larger', '350 to 500 lbs (157 to 225 kg)', '90 years', 'A world of giant rain-forest trees; sold in Atlantis, and about 1000 run wild in the forests of England', NULL, 'Larger predators', 'Optional pet or guard animal; its spiny back rules it out as a mount. Slave market: 150,000 credits untamed, 400,000 trained, up to 30% more near maximum M.D.C.', 'A lizard-like but warm-blooded, egg-laying tree climber, like a giant armored monkey with a bony head, huge hind claws and a stabbing tail, which hunts in packs and pounces on prey from above. The Splugorth sell it as a dragon killer.', 'Rifts World Book 2: Atlantis p.80-81');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('yazhing-multipede', 'Yazhing Multipede', 'animal', 'rifts', 0, 'Generally Anarchist or evil', '{"IQ":"1D4","ME":"1D6","MA":"1D4","PS":"2D6+12","PP":"2D6+10","PE":"3D6+10","PB":"1D4","Spd":"2D4x10"}', NULL, NULL, '1D6x10', '1D6', NULL, 'The stored M.D.C. is the main body of a common yazhing under 6 ft; a giant (15 to 30 ft) has 3D4x10+40. Head 40 (giant 90), each leg 5 (giant 20). I.Q. is animal. The size line also repeats the Yll Tree Climber''s size sentence word for word, a printing slip left out here.', NULL, NULL, '{"attacks":4,"initiative":2,"strike":1,"parry":1,"dodge":1,"roll":3}', 'Horror Factor 10 for a giant, none for a small one. +2 to strike dangling from above. +4 vs Horror Factor. Looks more dangerous than it is.', NULL, 'Nightvision 600 ft, infrared vision, tracks by smell 60%, prowl 62%, swims 80%, climbs 98%, running at full speed up walls, over smooth surfaces and upside down.', 'None', 'None', 'Typically 3 to 6 ft (0.9 to 1.8 m) long; giants 15 to 30 ft (4.6 to 9 m)', 'Giants 1500 lbs (675 kg)', 'Ten years', 'Follows the Splugorth and their minions everywhere; sold in Atlantis and found on the American east coast and Africa''s west coast', NULL, 'Larger predators and humanoids', 'A pest with no value when small; giants sell as guard or arena animals for 10,000 to 20,000 credits.', 'A giant alien centipede that scavenges carrion and refuse around Splugorth settlements like a cockroach. The rare giants prey on animals and even people, though they fight poorly. Lays 6D6 eggs twice a year.', 'Rifts World Book 2: Atlantis p.81'),
('eyes-of-eylor', 'Eyes of Eylor', 'alien', 'rifts', 0, 'Not applicable; programmable, typically evil or Anarchist', '{"IQ":"N/A","ME":"N/A","MA":"N/A","PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"50"}', NULL, NULL, '40', '150', '1D6x10+40', 'Attributes do not apply: total recall, but it never thinks for itself. Size sets the figures (stored: the small eye): M.D.C. 40 baseball size, 60 basketball, 100 twice that, 120 drum size; P.P.E. 150 small, 250 medium (printed 124 only), 400 large. Regenerates 1D4x10 M.D.C. a minute and can raise an Armor of Ithan field at once. Spd 50 (35 mph) flying or floating, up to 400 ft high (printed 124).', NULL, 10, NULL, 'Horror Factor, gases, poisons and drugs cannot affect it; it saves at +3 against magic and psionic attack. No combat or damage of its own.', 'No skills; prowl 70% and track humanoids 70% (printed 124).', 'Needs no food and survives anywhere, vacuum included. 20/20 sight over a wider spectrum including ultraviolet, nightvision 600 ft, telescopic to 6000 ft, 300x magnification, polarized (tells direction by the sun 88%); sees aura, the invisible, magic and P.P.E. without spending I.S.P. or P.P.E.', 'Programmed spells, any non-warlock spell of levels 1-8: small and medium eyes up to 11 spells twice each, as an 8th level mage; large eyes up to 20 spells three times each. Printed 73 puts a large eye at 12th level, printed 124 at 8th or 12th.', 'Minor psionic: empathy, telepathy (a receiver and mental link in bio-wizardry), see aura, see the invisible, sense evil, sense magic, total recall.', 'Baseball size up to a 50 gallon (190 liter) drum', 'About 2 lbs (0.9 kg) to 350 lbs (157.5 kg)', 'Unknown; perhaps 50,000 years, or effectively eternal', 'Said to come from Eylor, a dormant living planet the size of Jupiter; used throughout Atlantis in Splugorth bio-wizard devices', NULL, NULL, 'A living bio-wizard component, not a character. Slave market: over 100 million credits, very rarely sold.', 'Giant living eyes the Splugorth say come from the planet-being Eylor, used as power sources and sensors in slave barges, staves, floating eyes and statues. They hold and run programmed magic like a blank computer and never act on their own.', 'Rifts World Book 2: Atlantis p.72-73, 123-124'),
('eylor-floating-eye', 'Eylor Floating Eye', 'construct', 'rifts', 0, 'Not applicable; used as a tool', '{"Spd":"50"}', NULL, NULL, '60', '250', NULL, 'M.D.C. 60 is the eye itself; its glass-and-metal sphere has 50 to 100 more. Spd 50 (35 mph) flying or floating, up to 400 ft high. No I.S.P. line is printed for this device.', NULL, 14, NULL, 'Fights with its spells or an optional mini-blaster (jolt gun) in its lower cap, up to four blasts a melee, with damage and range doubled on a ley line. Optics and saves as the Eyes of Eylor.', 'Prowl 70%, track humanoids 70%.', 'Optics as the Eyes of Eylor.', 'Typically blinding flash, globe of daylight and chameleon (self only), each twice a day; 250 P.P.E.', NULL, 'An eye sealed in a glass orb with metal top and bottom caps', NULL, NULL, 'Five fly with every slave barge; also used alone to spy and scout', NULL, NULL, 'A bio-wizard device (the observation sphere or sensor probe).', 'The common observation sphere: an Eye of Eylor in a glass orb that floats about spying, scouting and herding slaves, the kind shown with the slave barge on the cover of Rifts.', 'Rifts World Book 2: Atlantis p.124'),
('eylor-seeker-hunter-eye', 'Eylor Seeker-Hunter Eye', 'construct', 'rifts', 0, 'Evil, typically Aberrant', '{"Spd":"50"}', NULL, NULL, '120', '400', '1D6x10+40', 'M.D.C. 120 is the eye itself; its sphere has 200 more. Spd 50 flying or floating. Psionics as the Eyes of Eylor.', NULL, 14, '{"attacks":5}', 'Five attacks a melee: three by magic plus two other actions. The optional laser and plasma blaster in its lower cap fire up to four blasts a melee each. Optics and saves as the Eyes of Eylor.', 'Prowl 70%, track humanoids 70%.', 'Optics as the Eyes of Eylor.', 'Eighteen spells, each three times a day, 400 P.P.E.: blinding flash, globe of daylight, globe of silence, chameleon (self only), eyes of the wolf, see the invisible, see aura, locate, turn dead, constrain being, fuel flame, paralysis: lesser, telekinesis, fire bolt, fire ball, call lightning, wisps of confusion, magic net.', 'As the Eyes of Eylor: empathy, telepathy, see aura, see the invisible, sense evil, sense magic, total recall.', 'A sphere the size of a 50 gallon drum', NULL, NULL, 'Guards areas and hunts enemies for the Splugorth', NULL, NULL, 'A bio-wizard device.', 'A larger, evil-aligned observation sphere that guards an area or seeks out and destroys enemies with attack magic and optional blasters.', 'Rifts World Book 2: Atlantis p.124'),
('rune-statue-dragon-head', 'Rune Statue: Dragon Head', 'construct', 'rifts', 0, 'Good, evil or selfish, set when made', '{"PS":"20","PP":"18","Spd":"N/A"}', NULL, NULL, NULL, NULL, NULL, 'Indestructible: no M.D.C. is printed; it can still be chained, restrained, encased or blocked. P.S. (supernatural) and P.P. are the minimums printed for every rune statue; a head is stationary.', NULL, NULL, '{"attacks":4}', 'Four attacks a melee; an animal or monster head has three and casts no spells. In an S.D.C. world the damage is S.D.C. Animates only four times a day, for 30 minutes each time; only a user of the statue''s own alignment (good, evil or selfish) can command it.', NULL, 'Every rune statue: an independent personality of average intelligence, limited telepathy, 20/20 vision, nightvision 300 ft (91.5 m) and sight of the invisible; impervious to psionics, poison, drugs, gases and magic that works on a mortal body, petrification included.', 'Six spells of levels 1-4, three times each a day, as a 4th level sorcerer.', NULL, 'A head or bust on a ship''s prow, stair, doorway, pillar or gable', NULL, NULL, 'Splugorth vessels and the homes of key minions', NULL, NULL, 'A rune weapon, never sold by the Splugorth; one is occasionally given as a reward for great service.', 'A carved dragon''s head or bust animated by a trapped life essence and rune magic, which bites and breathes fire from the building or vessel it is fixed to. Lion, snake and monster heads are made the same way.', 'Rifts World Book 2: Atlantis p.132'),
('rune-statue-dragon', 'Rune Statue: Dragon', 'construct', 'rifts', 0, 'Good, evil or selfish, set when made', '{"PS":"42","PP":"24","Spd":"58"}', NULL, NULL, NULL, NULL, '100', 'Indestructible: no M.D.C. is printed; it can still be chained, restrained, encased or blocked. P.S. is supernatural.', NULL, NULL, '{"attacks":6,"initiative":2,"strike":6,"parry":6,"dodge":6}', 'Six attacks a melee, two of which may be spells. Double damage to dragons. Animates only four times a day, for 30 minutes each time; only a user of the statue''s own alignment (good, evil or selfish) can command it.', NULL, 'Every rune statue: an independent personality of average intelligence, limited telepathy, 20/20 vision, nightvision 300 ft (91.5 m) and sight of the invisible; impervious to psionics, poison, drugs, gases and magic that works on a mortal body, petrification included. Its trapped essence must be a greater supernatural being such as an ancient dragon, god, greater elemental or demon lord.', 'Sixteen spells of levels 1-8, three times each a day, at the strength of an 8th level dragon.', 'Sense magic, sense evil, sense dragons and telepathy; 100 I.S.P.', 'A full-figure dragon', NULL, NULL, NULL, NULL, NULL, 'A rune weapon, never sold by the Splugorth; one is occasionally given as a reward for great service.', 'A full-figure dragon statue housing a greater supernatural essence, the most powerful and rarest rune statue, which loves combat and above all fighting real dragons.', 'Rifts World Book 2: Atlantis p.132'),
('rune-statue-gargoyle', 'Rune Statue: Gargoyle', 'construct', 'rifts', 0, 'Good, evil or selfish, set when made', '{"PS":"32","PP":"22","Spd":"27"}', NULL, NULL, NULL, NULL, NULL, 'Indestructible: no M.D.C. is printed; it can still be chained, restrained, encased or blocked. P.S. is supernatural. Spd 27 running, 66 flying (45 mph); it flies without a spell.', NULL, NULL, '{"attacks":5,"initiative":1,"strike":4,"parry":4,"dodge":4}', 'Five attacks a melee. Double damage to gargoyles. Animates only four times a day, for 30 minutes each time; only a user of the statue''s own alignment (good, evil or selfish) can command it.', NULL, 'Every rune statue: an independent personality of average intelligence, limited telepathy, 20/20 vision, nightvision 300 ft (91.5 m) and sight of the invisible; impervious to psionics, poison, drugs, gases and magic that works on a mortal body, petrification included.', 'Turn invisible (self only), chameleon, concealment, detect concealment, repel animals, fire bolt and energy bolt, each three times a day, at 4th level wizard strength.', NULL, 'About man-size, a little smaller than a real gargoyle', NULL, NULL, NULL, NULL, NULL, 'A rune weapon, never sold by the Splugorth; one is occasionally given as a reward for great service.', 'A monstrous man-sized gargoyle figure perched on masts, railings, towers, ledges and bookcases or standing free, which can fly and fight when it animates.', 'Rifts World Book 2: Atlantis p.132'),
('rune-statue-fire-breathing-lion', 'Rune Statue: Fire Breathing Lion', 'construct', 'rifts', 0, 'Good, evil or selfish, set when made', '{"PS":"32","PP":"22","Spd":"33"}', NULL, NULL, NULL, NULL, NULL, 'Indestructible: no M.D.C. is printed; it can still be chained, restrained, encased or blocked. P.S. is supernatural. Spd is running.', NULL, NULL, '{"attacks":4,"initiative":2,"strike":4,"parry":4,"dodge":4}', 'Four attacks a melee. Animates only four times a day, for 30 minutes each time; only a user of the statue''s own alignment (good, evil or selfish) can command it.', 'Prowl 55%, swim 55%, climb 55%, track by smell 70%; leaps 20 ft (6 m) high or long.', 'Every rune statue: an independent personality of average intelligence, limited telepathy, 20/20 vision, nightvision 300 ft (91.5 m) and sight of the invisible; impervious to psionics, poison, drugs, gases and magic that works on a mortal body, petrification included.', 'Turn invisible (self only), chameleon, concealment, detect concealment, repel animals, fire bolt and energy bolt, each three times a day, at 4th level wizard strength.', NULL, 'A lion', NULL, NULL, NULL, NULL, NULL, 'A rune weapon, never sold by the Splugorth; one is occasionally given as a reward for great service.', 'For reasons nobody knows, the Splugorth''s favorite statue design: a fire-breathing lion that pounces to knock its foes down.', 'Rifts World Book 2: Atlantis p.132-133'),
('rune-statue-combat-guardian', 'Rune Statue: Combat or Guardian Statue', 'construct', 'rifts', 0, 'Good, evil or selfish, set when made', '{"PS":"26","PP":"18","Spd":"24"}', NULL, NULL, NULL, NULL, NULL, 'Indestructible: no M.D.C. is printed; it can still be chained, restrained, encased or blocked. P.S. is supernatural. Spd is running.', NULL, NULL, '{"attacks":3,"initiative":1,"strike":3,"parry":3,"dodge":3}', 'Three attacks a melee; no fire breath. Animates only four times a day, for 30 minutes each time; only a user of the statue''s own alignment (good, evil or selfish) can command it.', NULL, 'Every rune statue: an independent personality of average intelligence, limited telepathy, 20/20 vision, nightvision 300 ft (91.5 m) and sight of the invisible; impervious to psionics, poison, drugs, gases and magic that works on a mortal body, petrification included. Animated by a tectonic entity or other lesser supernatural being; a little smarter and stronger than a golem.', NULL, NULL, 'Human size (6 ft/1.8 m) to about 20 ft (6 m) tall; humanoid or animal in form', NULL, NULL, NULL, NULL, NULL, 'A rune weapon, never sold by the Splugorth; one is occasionally given as a reward for great service.', 'The simplest rune statue: a humanoid or animal figure given life by a lesser supernatural being.', 'Rifts World Book 2: Atlantis p.133');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('true-atlantean', 'True Atlantean', 'humanoid', 'rifts', 1, 'Any; most are Principled, Scrupulous or Unprincipled', '{"IQ":"3D6+4","ME":"4D6+6","MA":"3D6+4","PS":"4D6+4","PP":"3D6","PE":"3D6+6","PB":"3D6+6","Spd":"4D6+6"}', 'PE+1D6', '50', NULL, '22', NULL, 'Hit points are P.E. plus 1D6 per level. S.D.C. 50 plus O.C.C., skill and tattoo S.D.C. (10 per tattoo). P.P.E. is the base 10 plus 12 from the two Marks of Heritage; add 6 per further tattoo and the P.P.E. of any magic O.C.C. Only Undead Slayers (Tattooed Men) are M.D.C. beings. Psionics as a human.', NULL, 12, NULL, 'Horror Factor 14 for an Undead Slayer. +2 to save vs all magic, +4 vs Horror Factor. Combat comes from the O.C.C.; most learn expert or martial arts hand to hand.', 'Literate in three or more languages; all can use the Marks of Heritage and any magic tattoo; operate dimensional pyramids 30% +5% per level.', 'Bears the Marks of Heritage (a staked heart against vampires, a flaming sword that makes an M.D.C. weapon) and may add up to four more tattoos; recovers P.P.E. twice as fast as a human (10 an hour, 15 meditating); cannot be transformed by any magic or supernatural means; keeps growing about an inch a century; senses vampires within 1000 ft and recognizes them 10% per level; senses ley lines, nexuses and Rifts and ley line phases as a line walker.', 'By O.C.C.', 'Standard, as a human.', '6 ft plus 1D4 inches, +1 inch per century (6.5 to 7 ft when old)', '170 lbs plus (76.5+ kg)', '500 years; dimensional time warps can stretch it past 1000', 'Clans scattered through the Megaverse; a few thousand have returned to Earth', NULL, 'Vampires and the Splugorth, their oldest foes', 'Any O.C.C.; most often ley line walker 15%, shifter 13%, techno-wizard 12%, temporal wizard 12%, undead slayer 10%, stone master 10%, nomad 9%, mind melter 5%, mind bleeder 4%, mystic 2%, other 8%.', 'Descendants of ancient Atlantis, reshaped by ages of ley line magic and dimensional travel into tall, long-lived, hardy humans. Most act as a self-appointed police force against the supernatural to atone for their ancestors'' disaster.', 'Rifts World Book 2: Atlantis p.15-16'),
('splugorth-conservator', 'Splugorth Conservator', 'alien humanoid', 'rifts', 1, 'Any, but usually Miscreant, Diabolic or Aberrant', '{"IQ":"3D6+2","ME":"18","MA":"3D6","PS":"50","PP":"21","PE":"21","PB":"1D6","Spd":"44"}', NULL, NULL, '1D4x100+350', '1D4x100+20', '2D4x10', 'M.D.C. includes 350 of bio-wizard natural plate armor; it never wears artificial armor. P.S. is supernatural; most physical attributes come from transmutation. The P.P.E. line says half is drawn from the Splugorth; the magic line gives 1D4x100 plus 20 from its eye of Eylor. Average level 1D4+4.', NULL, 16, '{"attacks":8,"strike":9,"parry":9,"dodge":6,"roll":4,"pull":4}', 'Eight physical attacks, or two spells and three physical; all augmentation is included. +3 to strike with a body block (1D4 M.D.). +2 vs psionics, +2 vs magic, +4 vs Horror Factor. Critical strike on 19-20. Obsessed with the hunt, it rolls twice on its own insanity table. Feeds on P.P.E. like a psi-stalker.', 'Basic math +30%, radio: basic +20% and scrambler +10%, pilot boats and hover vehicles +10%, climbing +20%, swimming +10%, wilderness survival and land navigation +20%; six W.P.s and four wilderness skills.', 'Bio-wizard augmentation: a second pair of arms, a stinging prehensile tail (paralysis 1D4 minutes, save 14), a scent-marking spray from the mouth (lasts 2D4 days), natural armor, finger claws, knuckle and elbow spikes, a molecular analyzer and motion sensor, and a third eye of Eylor. Nightvision 1000 ft, excellent color vision, turns invisible, sees the invisible, bio-regenerates 1D4x10 M.D.C. a minute, and can teleport (98%) to its Splugorth once a day.', 'Eight spells of levels 1-3, mostly for hunting, cast at a frozen 4th level.', 'Major psionic: astral projection, empathy, mind block, object read, sense magic, speed reading, telepathy, total recall.', '8 to 10 ft (2.4 to 3 m)', '250 to 400 lbs (112.5 to 180 kg)', '1000+ years', 'Only a few million across the whole Splugorth empire', 'The Splugorth, to whom it is normally fanatically loyal', 'Runaway slaves and enemies of the empire, which it hunts; renegades are killed on sight by any minion', 'Optional player character, but meant to be rare: a player Conservator must be a renegade freak. R.C.C. with its own skills; carries a lesser or greater rune weapon, and is issued two doses each of aerobes, aquarobes, dehibicila, purirobes and stasirobes, 1D4 mystic leeches and 1D4+1 zombitrons; half also have a pathic healer (printed 46).', 'A High Lord-born hunter who chose bio-borg transmutation: a hulking, four-armed, three-eyed, rhino-skinned predator with a stinging tail that lives to stalk and kill runaway slaves, like a bio-wizard crazy.', 'Rifts World Book 2: Atlantis p.45-47'),
('splugorth-overlord', 'Splugorth Overlord (Kydian)', 'alien humanoid', 'rifts', 1, 'Any, but usually Aberrant or Miscreant', '{"IQ":"2D6+3","ME":"3D6+3","MA":"3D6+3","PS":"3D6+20","PP":"3D6+3","PE":"4D6+3","PB":"2D6","Spd":"3D6"}', 'PE+2D6', '70', NULL, '1D4x10', NULL, 'Hit points are P.E. plus 2D6 per level. S.D.C. 70 plus skills; usually wears M.D.C. armor or becomes an M.D.C. being by bio-wizardry. P.S. is supernatural. Average level 1D4+2.', NULL, 10, '{"strike":2,"parry":2,"dodge":2,"roll":2,"pull":2}', 'Attacks come from Hand to Hand: Expert plus one racial and one for boxing. +1 to strike with a body block (1D4). +2 vs Horror Factor.', 'Basic math +20%, radio: basic and scrambler +10%, Dragonese/Elf, Gobblely, Faerie and Atlantean +40%, prowl +5%, boxing, wrestling, climbing and swimming +10%, W.P. blunt, sword, energy pistol and energy rifle, Hand to Hand: Expert; recognize magic tattoos 80%, circles 60%, enchantment 40%, magic items 35%; six other skills, three more W.P.s and seven secondary skills.', 'Nightvision 120 ft; sees in infrared and ultraviolet, so the world looks red, purple and blue; thick skin takes half damage from radiation, heat and fire.', 'Never learns magic; may gain powers from bio-wizard devices.', 'None, except through bio-wizardry.', '8 to 10 ft (2.4 to 3 m)', '400 to 600 lbs (180 to 270 kg)', '140 years', 'Kydian worlds throughout the Splugorth empire', 'The Splugorth, who saved their dying world 53,000 years ago', 'Any rogue Overlord is attacked by the minions', 'Optional player character, generally discouraged: a renegade, starting at level 1 or 2. R.C.C.: warrior/police. Standard issue: Staff of Pacification, Overlord power armor and bio-wizard microbes.', 'Huge, grey-purple, chin-horned Kydians from an overcrowded world the Splugorth rescued. Fast-breeding, even-tempered and fiercely loyal, they form the Splugorth''s main infantry and police; the bruiser on the book''s cover is one.', 'Rifts World Book 2: Atlantis p.47-48'),
('splugorth-powerlord', 'Splugorth Powerlord (Augmented Kydian)', 'alien humanoid', 'rifts', 1, 'Any, but usually Aberrant or Miscreant', '{"IQ":"2D6+3","ME":"3D6+3","MA":"3D6","PS":"40","PP":"21","PE":"21","PB":"2D6","Spd":"33"}', NULL, NULL, '75', '1D4x10+20', NULL, 'M.D.C. 75 from bio-wizard transformation, plus body armor. P.S. is supernatural and the physical attributes come from transmutation. The +20 P.P.E. comes from its eyes of Eylor. Average level 1D4+2.', NULL, 12, '{"strike":5,"parry":5,"dodge":5,"roll":2,"pull":2}', 'Attacks come from Hand to Hand: Martial Arts plus one racial, one for boxing and possibly more from augmentation. The printed bonuses include attribute bonuses. +3 to strike with a body block (1D6). +3 vs Horror Factor, +3 vs poison and magic.', 'As the Overlord.', 'Retractable forearm blades; eyes of Eylor giving 20/20 vision, nightvision 600 ft, telescopic sight to 6000 ft, 300x magnification and sight of aura, the invisible, magic and P.P.E.; mega-damage transformation; two more augmentations or symbiotes. Sees infrared and ultraviolet; half damage from radiation, heat and fire.', 'Never learns magic.', 'None, except through bio-wizardry.', '8 to 10 ft (2.4 to 3 m)', '400 to 600 lbs (180 to 270 kg)', '90 years', 'About a third of the Splugorth''s Kydian troops', 'The Splugorth', 'Renegades are hunted down by Conservators or the Sunaj', 'Optional player character, generally discouraged (a renegade, level 1 or 2). R.C.C.: elite warrior/special police. Standard issue: Staff of Power, Overlord power armor and a psi-interrogator.', 'A Kydian warrior rebuilt with bio-wizard implants into a mega-damage super soldier, an honor that cuts its life to about 90 years.', 'Rifts World Book 2: Atlantis p.48-49'),
('blind-warrior-women', 'Blind Warrior Women (Altara)', 'humanoid', 'rifts', 1, 'Any, but typically Anarchist or evil', '{"IQ":"1D6+10","ME":"1D6+15","MA":"1D6+16","PS":"1D6+22","PP":"1D6+21","PE":"1D6+22","PB":"2D6+14","Spd":"2D6+22"}', '1D4x10', '2D6x10', NULL, '2D6', '3D6x10', 'Hit points 1D4x10 plus 1D6 per level. M.D.C. only from magic or armor: the rubbery suit gives 30, the talisman''s Armor of Ithan 100. I.S.P. +1D6 per level. Average level 2D4+2 (4th to 10th).', NULL, 12, '{"attacks":6,"initiative":2,"strike":1,"parry":2,"dodge":2,"roll":4,"pull":2,"damage":2}', 'Six attacks regardless of level or training; critical strike on 18-20; fights with paired weapons; no penalty for blindness or darkness. +2 vs psionics, +1 vs magic, +4 vs Horror Factor, +10% vs coma/death. Storms, rain, snow, dust and smoke halve her radar, hearing, smell and combat bonuses.', 'Hand to Hand: Martial Arts, boxing, gymnastics, general athletics, running, climbing and swimming +10%, prowl, land navigation +5%, wilderness survival +10%, identify plants +5%, skinning +10%, preserve food and cook +5%, demon and monster lore +5%, basic math +20%, intelligence +5%, paramedic +10%, hunting; W.P. archery, blunt, knife, sword, energy pistol and energy rifle; six secondary skills.', 'Born blind but compensates psionically: heightened hearing, smell (recognize odors 90%, people 70%, poisons 80%, track 80%) and touch (66%), a radar sense to 1200 ft, and great endurance. Reproduces by ectoplasmic cloning; the clone has half her level.', 'A talisman casts Armor of Ithan (100 M.D.C., 10 minutes) three times a day and recharges daily.', 'Sixth sense, presence sense, empathy, sense magic, sense evil, object read, clairvoyance, mind block.', '5.8 to 6.2 ft (1.7 to 1.9 m)', '160 lbs (72 kg)', NULL, 'Altara, a world the Splugorth took some 2000 years ago; four to six ride with every slave barge', 'The Splugorth Slavers they serve', 'About a quarter hate their captivity; runaways are hunted by Slavers, their sisters and Conservators', 'Optional player character (a rogue unwelcome in Atlantis). R.C.C. with its own skills.', 'Sterile, cloned, beautiful and blind warrior women conditioned for generations to serve the Splugorth, who ride the slave barges to capture and herd slaves with martial arts and psionic senses.', 'Rifts World Book 2: Atlantis p.50-51'),
('kittani-warrior', 'Kittani Warrior', 'alien humanoid', 'rifts', 1, 'Any, but usually Aberrant or Miscreant', '{"IQ":"2D6+14","ME":"2D6+14","MA":"2D6+10","PS":"3D6+8","PP":"3D6+3","PE":"3D6+6","PB":"2D6+2","Spd":"3D6"}', 'PE+1D6', '50', NULL, '1D6', '2D4x10', 'Hit points are P.E. plus 1D6 per level. S.D.C. 50 plus skills; fights in M.D.C. power armor. I.S.P. +1D6+1 per level. Average NPC level 1D4+1.', NULL, 10, '{"strike":1,"parry":1,"dodge":1,"roll":1,"pull":1}', 'Horror Factor 10 only in power armor or a bot. Attacks come from Hand to Hand: Expert plus one for boxing. +1 to strike with a body block. +2 vs Horror Factor. Often fights to the death rather than admit defeat.', 'Basic and advanced math +20%, radio: basic and scrambler +15%, surveillance +10%, basic electronics +10%, intelligence +10%, pick locks +10%, pilot robots and power armor, robot combat: basic, two pilot skills, Dragonese/Elf and Gobblely +30%, boxing or wrestling, climbing and swimming +10%, W.P. blunt, sword, energy pistol, energy rifle and three more, Hand to Hand: Expert; four other skills, three W.P.s and five secondary skills.', 'Good color vision; other senses about human.', 'None; the Splugorth forbid it and kill any Kittani caught studying it.', 'Major psionic: mind block, sixth sense, speed reading, total recall, object read, telemechanics.', '5 to 6 ft (1.5 to 1.8 m)', '170 to 250 lbs (76.5 to 112.5 kg)', '120 years', 'Throughout the Splugorth empire, most of all in Splynncryth''s domains', 'The Splugorth, their allies for 38,000 years', 'The Mechanoids, who overran their worlds; Kittani traitors are hunted down', 'Optional player character, starting at level 1 or 2. One of three Kittani R.C.C.s that share these stats (Warrior, Field Mechanic/Scientist, Espionage Agent).', 'Brilliant, cheerful and cruel ape-like aliens with six-fingered hands and huge skulls, refugees Splynncryth saved from the Mechanoids. Master engineers whose power armor and bots outclass Triax, they long to conquer worlds on their own again.', 'Rifts World Book 2: Atlantis p.52-53'),
('kittani-field-mechanic', 'Kittani Field Mechanic/Scientist', 'alien humanoid', 'rifts', 1, 'Any, but usually Aberrant or Miscreant', '{"IQ":"2D6+14","ME":"2D6+14","MA":"2D6+10","PS":"3D6+8","PP":"3D6+3","PE":"3D6+6","PB":"2D6+2","Spd":"3D6"}', 'PE+1D6', '50', NULL, '1D6', '2D4x10', 'Hit points are P.E. plus 1D6 per level. S.D.C. 50 plus skills; fights in M.D.C. power armor. I.S.P. +1D6+1 per level. Average NPC level 1D4+1.', NULL, 10, '{"strike":1,"parry":1,"dodge":1,"roll":1,"pull":1}', 'Horror Factor 10 only in power armor or a bot. Attacks come from Hand to Hand: Expert plus one for boxing. +1 to strike with a body block. +2 vs Horror Factor. Often fights to the death rather than admit defeat.', 'Basic and advanced math +20%, radio: basic +15%, electrical and mechanical engineer +10%, robot electronics +10%, robot mechanics +15%, weapons engineer +5%, computer repair and operation +10%, hacking +15%, land navigation +5%, pilot robots and power armor, motorcycle +10%, two pilot skills +5%, Dragonese/Elf and Gobblely +30%, climbing and swimming +10%, W.P. energy pistol, energy rifle and one more, Hand to Hand: Expert; six other skills, three W.P.s and six secondary skills.', 'Good color vision; other senses about human.', 'None; the Splugorth forbid it and kill any Kittani caught studying it.', 'Major psionic: mind block, sixth sense, speed reading, total recall, object read, telemechanics.', '5 to 6 ft (1.5 to 1.8 m)', '170 to 250 lbs (76.5 to 112.5 kg)', '120 years', 'Throughout the Splugorth empire, most of all in Splynncryth''s domains', 'The Splugorth, their allies for 38,000 years', 'The Mechanoids, who overran their worlds; Kittani traitors are hunted down', 'Optional player character, starting at level 1 or 2. Same stats as the Kittani Warrior; only the skills differ.', 'The Kittani technician and scientist: the same brilliant, ape-like race as the warrior, trained to build and repair robots, power armor, weapons and computers.', 'Rifts World Book 2: Atlantis p.52-53'),
('kittani-espionage', 'Kittani Espionage Agent', 'alien humanoid', 'rifts', 1, 'Any, but usually Aberrant or Miscreant', '{"IQ":"2D6+14","ME":"2D6+14","MA":"2D6+10","PS":"3D6+8","PP":"3D6+3","PE":"3D6+6","PB":"2D6+2","Spd":"3D6"}', 'PE+1D6', '50', NULL, '1D6', '2D4x10', 'Hit points are P.E. plus 1D6 per level. S.D.C. 50 plus skills; fights in M.D.C. power armor. I.S.P. +1D6+1 per level. Average NPC level 1D4+1.', NULL, 10, '{"strike":1,"parry":1,"dodge":1,"roll":1,"pull":1}', 'Horror Factor 10 only in power armor or a bot. Attacks come from Hand to Hand: Expert plus one for boxing. +1 to strike with a body block. +2 vs Horror Factor. Often fights to the death rather than admit defeat.', 'Basic and advanced math +10%, radio: basic and scrambler +10%, basic electronics +5%, computer operation +10%, hacking +5%, escape artist +5%, pick locks and pockets +10%, intelligence and streetwise +10%, pilot robots and power armor, motorcycle +10%, jet pack, two pilot skills +5%, Dragonese/Elf and Gobblely +30%, climbing +10%, W.P. energy pistol, energy rifle and two more, Hand to Hand: Expert; five other skills, three W.P.s and five secondary skills.', 'Good color vision; other senses about human.', 'None; the Splugorth forbid it and kill any Kittani caught studying it.', 'Major psionic: mind block, sixth sense, speed reading, total recall, object read, telemechanics.', '5 to 6 ft (1.5 to 1.8 m)', '170 to 250 lbs (76.5 to 112.5 kg)', '120 years', 'Throughout the Splugorth empire, most of all in Splynncryth''s domains', 'The Splugorth, their allies for 38,000 years', 'The Mechanoids, who overran their worlds; Kittani traitors are hunted down', 'Optional player character, starting at level 1 or 2. Same stats as the Kittani Warrior; only the skills differ. About 10% carry a lesser rune or bio-wizard weapon and 30% have minor bio-wizard augmentation.', 'The Kittani spy and saboteur: the same brilliant, ape-like race as the warrior, trained in infiltration, intelligence and theft, and sometimes armed with microbes and parasites for special missions.', 'Rifts World Book 2: Atlantis p.52-54');
INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('murvoma-metztla', 'Murvoma Metztla', 'alien', 'rifts', 1, 'Any, but almost always Diabolic or Miscreant', '{"IQ":"2D6+6","ME":"22","MA":"2D6","PS":"30","PP":"23","PE":"24","PB":"1D6","Spd":"3D6+2"}', NULL, NULL, '400', '1D6x10', '4D4x10', 'M.D.C. by location: mouth tentacles (6) 60 each, octopus tentacles (8) 80 each, sensor lobe 300, eyes (2) 40 each, main body 400 (stored). P.S. and P.P. are those of the tentacles. Spd is crawling or climbing; swims 2D6x10; cannot fly. I.S.P. +10 per level. The stat block prints P.P.E. 1D6x10 and the magic line 1D4x10 (stored: the stat block). Typically 5th level, sometimes up to 7th.', NULL, 14, '{"attacks":6,"initiative":2,"strike":6,"parry":6,"dodge":4,"roll":2,"pull":4}', 'Six hand to hand or four psionic attacks, or two of each. The printed bonuses include everything. +2 to strike with a body ram. +6 vs Horror Factor, +4 vs psionics, +5 vs magic and poison. Critical strike on 19-20. Blinded, it loses 2 from each combat bonus.', 'Basic and advanced math, biology, chemistry, holistic medicine, demon and monster lore, land and underwater navigation and wilderness survival, all +15%; Dragonese/Elf and four other languages.', 'Fourteen agile 10 ft tentacles, six with beaked mouths and eight with suckers, that regrow in 2D4 days and can pin and crush; amplified hearing, sonar and keen smell (tracks blood and decay 80%); nightvision 300 ft, sharper sight and infrared underwater; swims 98%, climbs 96%, prowl 50% (90% still underwater); breathes air or water.', 'P.P.E. only; does not study magic.', 'Master psionic: levitation, death trance, telekinesis, healing touch, deaden pain, psychic diagnosis, psychic surgery, detect psionics, sense magic, see aura, see the invisible, presence sense, telepathy, total recall, astral projection, ectoplasm, group mind block, mind block auto-defense.', '8 to 12 ft (2.4 to 3.6 m) tall, about 8 ft (2.4 m) long', 'One ton', '3000 years', 'Metztla hives, tending the eggs and the queen; travels in groups of two to eight', 'Other Metztla; the Splugorth and High Lords favor them and invite their help', NULL, 'Available as a player character. R.C.C. 18% of the Metztla are Murvoma.', 'The only shell-less Metztla: a rubbery, octopus-like nurse and torturer caste whose beaked mouth-tentacles work like scalpels. Mean and intolerant of intruders, yet warmly regarded by the Splugorth.', 'Rifts World Book 2: Atlantis p.58-60'),
('adarok', 'Adarok', 'giant', 'rifts', 1, 'Any, but typically good or selfish', '{"IQ":"2D6+2","ME":"3D6+6","MA":"3D6+6","PS":"3D6+42","PP":"3D6+6","PE":"3D6+12","PB":"2D6","Spd":"4D6"}', NULL, NULL, '1D4x100+400', '2D4x10+45', '6D6+12', 'Spd is running; flies 2D4x10. P.P.E. is 2D4x10+45 in the stat block and 2D4x10+40 in the magic line (stored: the stat block), +10 per level. Never wears M.D.C. armor. Supernatural strength. Average level 1D4+1; dragon experience table.', NULL, 15, '{"attacks":4,"initiative":1,"strike":4,"parry":4,"dodge":-6}', 'Four melee actions, +1 at levels 4, 7, 10 and 13; as many psionic attacks, or two by magic. +4 to strike with a body block. +5 vs Horror Factor. Impervious to cold, fire and poison, magical ones included.', 'Basic math +10%, land navigation and wilderness survival +20%, faerie and demon lore +10%, dance +10%, W.P. blunt and targeting; native Adoran 98%, Gobblely and Dragonese/Elf 85%; four other skills and four secondary skills.', 'Nightvision 600 ft, sees the invisible, polarized vision (tells direction by the sun 90%), swims 40%, climbs 60%, impervious to cold, fire and poison, communicates psionically.', 'Knows the earth warlock spells chameleon, fool''s gold, identify minerals, identify plants, grow plants, wither plants, dig and encase object in stone; gains one earth spell of levels 1-3 per level by meditation.', 'Minor psionic: telepathy, sense evil, mind block.', '40 to 60 ft (12.2 to 18.3 m) tall; wingspan 100 ft (30.5 m) open', '18 to 28 tons', '800 years', 'Forests and jungles; slaves and escapees in Atlantis, small communities in England, eastern Canada and Asia', 'Anyone of like alignment who treats them kindly', 'The Splugorth and their minions, enslaving mages and most supernatural beings; people who take them for demons', 'Optional player character. R.C.C. with limited skills. Never uses bio-wizard devices or cybernetics. Slave market: 4 to 10 million credits.', 'A gentle, mostly vegetarian winged giant that looks like a living, demon-faced shard of mountain. Slow to anger but devastating when roused, it would rather calm or avoid those who attack it as a demon.', 'Rifts World Book 2: Atlantis p.69-70'),
('erta', 'Erta', 'monster', 'rifts', 1, 'Any, but generally evil', '{"IQ":"2D4+3","ME":"3D6+4","MA":"1D6","PS":"3D6+12","PP":"3D6+4","PE":"3D6+6","PB":"3D6","Spd":"5D6"}', NULL, NULL, '4D4x10', '4D6x10', NULL, 'Spd is crawling. P.P.E. +2D4 per level. Average level 1D4+1; stone master experience table.', NULL, 13, '{"attacks":5,"initiative":1,"strike":3,"parry":2,"dodge":2,"roll":2}', 'Five attacks, +1 at levels 3, 6, 9 and 12. +6 vs Horror Factor, +2 vs psionics and poison; impervious to all magic. May use weapons but prefers its own body; never wears armor.', 'Basic math +5%, land navigation +25%, wilderness survival +20%, track animals +15%, W.P. knife; a Gobblely dialect, and Dragonese/Elf 98% for slaves (illiterate); five other skills, no secondary skills.', 'Nightvision 300 ft, black and white vision, keen hearing, tracks by sound and ground vibration 60%, swims 50%, climbs 75%, breathes without air; moves through rock and earth like a stone master.', 'Natural stone master powers: mold, push, carry (1000 times its P.S.), move and levitate stone, sense water and elementals underground, find secret passages in stone. No gem magic or pyramid lore.', 'None', 'Typically 10 to 20 ft (3 to 6 m)', '500 to 1000 lbs (225 to 450 kg)', '250 years', 'Sold in Atlantis; escaped wild in the Atlantean wilderness and Eastern Europe', 'Loners, or packs of two to six', 'Larger predators, Splugorth minions and humanoids', 'Optional player character, though the book does not recommend it. Slaves carry a bio-wizard enslaver implant. Slave market: 50,000 credits wild, 300,000 with an enslaver.', 'A cruel subterranean serpent with a four-armed humanoid torso, spiked tail and huge underslung jaw, which bursts out of earth or rock to seize prey and delights in torment. The Splugorth use them for tunneling and construction.', 'Rifts World Book 2: Atlantis p.71-72'),
('hawrk-duhk', 'Hawrk-duhk', 'alien humanoid', 'rifts', 1, 'Any, but generally Anarchist or Unprincipled', '{"IQ":"3D4+2","ME":"4D6","MA":"1D6","PS":"3D6+6","PP":"3D6+2","PE":"3D6+2","PB":"1D6+3","Spd":"3D6"}', NULL, NULL, '3D4x10', '4D6', '6D6+20', 'Spd is running; swims 2D4x10. Average level 1D4; city rat/vagabond experience table.', NULL, 8, '{"attacks":3,"initiative":3,"strike":1,"parry":3,"dodge":3,"roll":2}', 'Three attacks, +1 at levels 6 and 11. +3 vs Horror Factor, +1 vs psionics and poison; impervious to all magic. Uses weapons only in self-defense.', 'Basic math +10%, land navigation +20%, wilderness survival +10%, preserve food +5%, W.P. blunt; Hawrkin and Dragonese/Elf 98% (illiterate); six other skills and four secondary skills.', 'Nightvision 100 ft, hawk-like distance vision, sees the invisible and underwater, keen hearing, tracks by sight 40%, climbs 30%, swims 98% for three hours untiring, holds its breath eight minutes, oily water-resistant feathers and fur; impervious to magic.', 'None', 'Major psionic: sense evil, sense magic, presence sense, mind block, detect psionics, increase healing, psychic purification, resist fatigue.', '6 to 8 ft (1.8 to 2.4 m)', '300 lbs (135 kg)', '50 years', 'Sold in Atlantis; found in North America, Europe and Africa', 'Friendly to most races', 'Hawrk-ka, large predators and humanoids', 'Optional player character. R.C.C. with limited skills. Slave market: 150,000 to 250,000 credits.', 'Flightless, duck-billed bird people: peaceful, curious, community-minded flock dwellers who mate for life and make docile slaves and servants for the Splugorth.', 'Rifts World Book 2: Atlantis p.74-75'),
('hawrk-ka', 'Hawrk-ka', 'alien humanoid', 'rifts', 1, 'Any, but generally Anarchist or evil', '{"IQ":"3D4","ME":"4D6","MA":"1D6","PS":"3D6+10","PP":"3D6+6","PE":"3D6+6","PB":"3D6","Spd":"4D6"}', NULL, NULL, '4D4x10', '2D6', '4D6+10', 'Spd is running; flies 2D6x10+30, for up to four hours. Average level 1D4; head hunter experience table.', NULL, 13, '{"attacks":5,"initiative":4,"strike":2,"parry":3,"dodge":3,"roll":3}', 'Five attacks, +1 at levels 5, 10 and 15. +3 to strike flying and diving from above. +5 vs Horror Factor, +1 vs psionics and poison; impervious to all magic. Never wears armor.', 'Basic math +5%, land navigation and wilderness survival +20%, preserve food +5%, W.P. blunt; Hawrkin and Dragonese/Elf 98% (illiterate); four other skills and four secondary skills.', 'Nightvision 100 ft, hawk-like vision, sees the invisible, keen hearing, tracks by sight 60% and smell 45%, swims 30%, climbs 60%; impervious to magic.', 'None', 'Minor psionic: sense magic, presence sense, mind block.', '6 to 10 ft (1.8 to 3 m)', '500 lbs (225 kg)', '50 years', 'Sold in Atlantis; found in North America, Europe and Africa', 'Loners who may work with a group', 'Larger predators and humanoids; it respects the Splugorth and their minions', 'Optional player character. R.C.C. with limited skills. Slave market: 100,000 to 300,000 credits.', 'A fierce, not very bright, magic-proof bird of prey from the zembahk''s world that hunts zembahk and hawrk-duhk and loves the kill; the Splugorth sell them as hunters and guards. Three females to each male.', 'Rifts World Book 2: Atlantis p.75-76'),
('hawrk-ohl', 'Hawrk-ohl', 'alien humanoid', 'rifts', 1, 'Any, but generally Anarchist or evil', '{"IQ":"3D4","ME":"4D6","MA":"3D6","PS":"3D6+20","PP":"3D6+6","PE":"3D6+6","PB":"3D6","Spd":"4D6"}', NULL, NULL, '4D4x10', '3D6', '4D6+10', 'Spd is running and climbing. Average level 1D4+1; head hunter experience table.', NULL, 12, '{"attacks":5,"initiative":3,"strike":4,"parry":4,"dodge":3,"roll":2}', 'Five attacks, +1 at levels 5, 10 and 15. +3 to strike leaping from above; critical strike on a natural 19-20. +4 vs Horror Factor, +1 vs psionics and poison; impervious to all magic.', 'Basic math +5%, land navigation and wilderness survival +15%, preserve food +10%, W.P. archery and targeting, knife and sword; Hawrkin and Dragonese/Elf 98% (illiterate); six other skills and four secondary skills.', 'Prehensile, double-jointed feet, nightvision 1000 ft, good color vision, sees the invisible, keen hearing, superior smell (track 80%, recognize 85%), swims 60%, climbs 98%, acrobatics 80%, prowl 80%; impervious to magic.', 'None', 'Minor psionic: sixth sense, sense evil, mind block.', '10 to 14 ft (3 to 4.3 m)', '700 lbs (315 kg)', '50 years', 'Sold in Atlantis; found in North America, Europe and Africa', 'Its flock-tribe of 4 to 24; works well in groups but distrusts strangers and mages', 'Larger predators, the supernatural and humanoids; hates the hawrk-ka and hawrk-duhk', 'Optional player character. R.C.C. with limited skills. Slave market: 250,000 to 400,000 credits.', 'Powerful owl-like bird men, cousins of the other hawrks and likewise immune to magic, who ambush from trees. More social than the hawrk-ka, they share territory in small tribes and take readily to weapons, favoring heavy, magic and bow weapons and vibro-blades.', 'Rifts World Book 2: Atlantis p.76-77'),
('shaydor-intel', 'Shaydor Intel', 'alien', 'rifts', 1, 'Any; adventurers are generally selfish or good', '{"IQ":"3D6","ME":"4D6+4","MA":"3D6","PS":"2D6+4","PP":"2D6+4","PE":"3D6","PB":"2D6","Spd":"3D6+4"}', NULL, NULL, '2D4x10+30', '4D6', 'ME+1D4x10', 'I.S.P. +1D6 per level. Average level 1D4+2; mind melter experience table.', NULL, 9, '{"attacks":4,"initiative":5,"strike":4,"parry":4,"dodge":4,"roll":1}', 'Four physical or psionic attacks, +1 at levels 3, 7, 11 and 15. +5 vs Horror Factor, +4 vs psionics and all mind control, +3 vs magic illusions, +5% vs coma/death.', 'Basic math +15%, land navigation and wilderness survival +10%; Shaydorian and Dragonese/Elf 98% (literate) and two more languages +15%; four W.P.s; eight other skills and five secondary skills.', 'Prehensile feet, double-jointed and ambidextrous; superior color vision, infrared, nightvision 600 ft and 3x close magnification; antennae sense air movement and smell (recognize smells 65%, individuals 50%, track 40%); swims, climbs and prowls 60%.', 'None; may use magic items.', 'Minor psionic: telemechanics, total recall, speed reading, mind block.', '9 to 11 ft (2.7 to 3.3 m)', '130 lbs (58.5 kg)', '150 years', 'Sold in Atlantis; found throughout the world and beyond', 'Many serve the Splugorth and their minions; a few have joined True Atlanteans', 'Predators and supernatural monsters; most dislike the Shaydor Spherians', 'Optional player character. R.C.C. with limited skills. Slave market: 400,000 to 550,000 credits; mechanics fetch the most.', 'The bug-eyed, antennaed, stilt-legged cousin of the Shaydor Spherian: a mammal, quicker and more aggressive, with few psionic powers but strong resistance to mind control. Many serve the Splugorth; others oppose them fiercely.', 'Rifts World Book 2: Atlantis p.79-80'),
('zembahk', 'Zembahk', 'alien', 'rifts', 1, 'Any, but usually Principled, Scrupulous or Unprincipled', '{"IQ":"2D6+2","ME":"4D6+4","MA":"4D6+4","PS":"1D6","PP":"2D6","PE":"3D6+4","PB":"1D6","Spd":"2D6"}', NULL, NULL, '2D6x10', '5D6x10', '1D4x100+200', 'P.P.E. +10 per level. Never wears M.D.C. armor. Average level 1D4; dragon experience table.', NULL, 10, '{"attacks":4,"strike":3,"parry":3,"automatic_dodge":6}', 'Four melee actions, +1 at levels 4, 7, 10 and 13; as many psionic attacks, or two by magic. Its dodge (+6) is automatic and costs no action. +4 vs Horror Factor, +1 vs psionics, magic and poison.', 'Basic math +30%, land navigation +10%, wilderness survival +15%, identify plants +5%, detect ambush and concealment +5%, faerie and demon lore +5%, art +15%, dance +10%; senses ley lines and magic, ley line transmission (images) and phasing as a line walker; recognize runes, rune weapons and bio-wizard devices 65%. No related or secondary skills.', 'Nightvision 600 ft, sees the invisible, polarized vision (88%), prowl 48%, swims and climbs 88%, communicates psionically; feeds on small amounts of magic energy.', 'Knows every spell of levels 1-5 by instinct and gains two spells of levels 6-11 each level by meditation (no metamorphosis or summoning).', 'Mind melter equivalent: all healing and sensitive powers plus alter aura, ectoplasm, impervious to cold and fire, super bio-regeneration, empathic transmission, group mind block, mind block auto-defense, mind bolt, psi-sword (from the tail) and telekinetic force field.', '3 to 5 ft (0.9 to 1.5 m) long', '6 to 10 lbs (2.7 to 4.5 kg)', '300 years (half or less as a bio-wizard component)', 'A secret homeworld where the Splugorth breed them; escapees near any Splugorth colony, Earth included', NULL, 'The Splugorth, who enslave them; the hawrk predators of their world', 'Optional player character. R.C.C. with limited skills. Never uses bio-wizard devices or cybernetics. Slave market: 400,000 to 600,000 credits.', 'Gentle, pink, one-eyed worms steeped in magic and psionic power, bred and harvested by the Splugorth as living power sources for bio-wizard devices. Naive, kind and curious, they live in harmony with nature.', 'Rifts World Book 2: Atlantis p.82-83');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('splynncryth', 'Splynncryth', NULL, 'Lord Splynncryth, the Splugorth ruler of Atlantis', 'rifts', 'Splugorth (alien intelligence)', '10th level ley line walker, rune master, stone master, tattoo master and shifter/summoner (special NPC R.C.C.)', 10, 'Anarchist', '72,000 years (young for a Splugorth)', '12 ft (3.6 m) tall and 25 ft (7.6 m) across; tentacles about 50 ft (15 m)', '35 tons', '{"IQ":30,"ME":32,"MA":28,"PS":50,"PP":26,"PE":28,"PB":3,"Spd":50}', NULL, NULL, 56000, 13000, 3000, NULL, 17, '{"attacks":11,"initiative":6,"strike":2,"parry":2,"dodge":-2}', 'Eleven physical, five psionic or two magic attacks a melee. Critical strike on 18-20. Dodge is printed as minus 2. +6 vs Horror Factor, +2 on all saves, immune to mind control (even a vampire''s). Silver and magic weapons do triple damage. M.D.C. by location: giant eye 1200, eye film cover 2000, eye spines (6) 500 each, main tentacles (5) 800 each, secondary tentacles (6) 500 each, main body 56,000 (stored). At zero on the main body he is only impaired (three physical, two psionic, one magic attack, no bonuses); negative 4000 destroys him. Away from any P.P.E. source his M.D.C., P.P.E. and I.S.P. fall to a quarter.', '[{"name":"Language: Dragonese/Elf","pct":98},{"name":"Literacy: Dragonese/Elf","pct":98},{"name":"Language: Faerie","pct":98},{"name":"Literacy: Faerie","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Literacy: Gobblely","pct":98},{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":98},{"name":"Language: Euro","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Language: Atlantean","pct":98},{"name":"Literacy: Atlantean","pct":98},{"name":"Intelligence","pct":98},{"name":"Swimming","pct":98},{"name":"Climbing","pct":98},{"name":"Palming","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Mathematics: Advanced","pct":98},{"name":"Land Navigation","pct":98},{"name":"Pick Pockets","pct":71},{"name":"Lore: Demons & Monsters","pct":71},{"name":"Lore: Faeries & Creatures of Magic","pct":71},{"name":"Writing","pct":71}]', 'Languages and literacy at 98% as printed, with magic for any other tongue. Magic knowledge: creates magic tattoos, reads runes and mystic symbols, recognizes and creates circles, recognizes wards and enchantment, and recognizes magic items and weapons 90%. Weapon and science skills are not studied.', 'Superior color vision and nightvision to 1000 ft (310 m); sees the invisible; bio-regenerates 2D6x10 M.D.C. a minute and regrows limbs in 72 hours, needs no air. Dimensional teleport 98% to any world he rules, and can open a rift to anywhere he has been. Teleports up to 600 miles; possession; turns, animates and controls up to 600 dead; healing touch 1D6x10, restoration, resurrection, stone to flesh, remove curse; summons 2D6 High Lords or 6D6 lesser minions three times a day. Can split his essence into 4D4 fragments that possess hosts on other worlds.', 'All spells and ritual magic, as a line walker; all stone master powers; the making of magic tattoos, rune weapons and bio-wizardry. 13,000 P.P.E.', 'All sensitive, healing and super psionic powers, as a 10th level psionic.', NULL, NULL, 'Uses bio-wizard devices and rune weapons only when he must, relying on his magic and psionics.', NULL, 'A superb strategist, manipulator, negotiator and salesman who lets others do his dirty work. Delights in the Sunaj alliance he brokered and looks forward to their eventual betrayal for the excitement; amused by the war in Europe.', 'His minions; the Sunaj, whose personal liaison he is; Styphathal of Dragcona. He has quietly helped the gargoyles in Europe.', 'True Atlanteans, the Splugorth''s ancient foes.', 'The Splugorth who conquered Atlantis and three other worlds: a slimy 35-ton mound with one great spine-crowned eye and eleven tentacles, four of them toothed mouths. He spends his time building Atlantis, selling slaves, working magic and trading across the dimensions.', 'Rifts World Book 2: Atlantis p.39-41'),
('styphathal', 'Styphathal', NULL, 'The Corruptor, Son of Styphon; ruler of Dragcona and self-proclaimed god of the Dragonwright cult', 'rifts', 'Ancient black horned dragon', 'Equal to an 11th level spell caster; 6th level stone master', 11, 'Aberrant', '6013 years', NULL, NULL, '{"IQ":28,"ME":27,"MA":30,"PS":52,"PP":19,"PE":24,"PB":26,"Spd":60}', NULL, NULL, 9500, 1100, 242, NULL, 19, NULL, 'Spd 60 running, 180 flying. M.D.C. is his main body. His entry prints no attacks per melee or combat bonuses; other powers are standard for a horned dragon.', NULL, NULL, 'Standard for a horned dragon.', 'Every spell of levels 1-10 plus remove curse, summon fog, summon entity, time hole, sanctum, id barrier, close rift and dimensional portal, all at 11th level; a 6th level stone master, taught tattoo magic by Splynncryth himself.', 'All the usual powers of a horned dragon.', NULL, NULL, 'The Tooth of Styphon, a greatest rune sword (1D6x10 M.D.) with all the standard powers: it drinks souls, heals as a greater rune weapon, and casts luck curse, minor curse, phobia curse, compulsion and remove curse (66%). It is said to hold Styphon''s essence, which is untrue: Styphon lives.', NULL, 'A brilliant strategist, manager and persuasive, seemingly sincere liar who craves power and worship without taking foolish risks; generous one moment and cruel the next, and intolerant of anyone who embarrasses him or will not play along. Loyal to Splynncryth while he lives.', 'Lord Splynncryth; the Federation of Magic, which follows his cult', 'His brother Stydro, whom he betrayed; vampires, hunted in Dragcona on Splynncryth''s order', 'An ancient dragon who calls himself the dragon-god Styphon''s eldest son, rules the city of Dragcona and invented the death cult of Dragonwright, a sham he uses to whip the Federation of Magic into a frenzy.', 'Rifts World Book 2: Atlantis p.33'),
('stydro', 'Stydro', NULL, 'The Great Horned Dragon; notable asylum inmate', 'rifts', 'Ancient great horned dragon', '16th level horned dragon; 4th level shifter', 16, 'Diabolic', NULL, NULL, NULL, '{"IQ":27,"ME":30,"MA":28,"PS":48,"PP":20,"PE":22,"PB":28,"Spd":50}', NULL, NULL, 7075, 1000, 301, NULL, 17, NULL, 'Spd 50 running, 160 flying. M.D.C. is his main body. His entry prints no attacks per melee or combat bonuses; other powers are standard for his species.', NULL, NULL, 'Standard for his species.', 'Every spell of levels 1-15; also a 4th level shifter.', 'All the usual powers of a horned dragon, at 16th level, plus empathic transmission, super telekinesis, pyrokinesis and bio-manipulation at 5th level strength.', NULL, NULL, NULL, NULL, 'A former champion of light turned diabolic and obsessed with getting out. He means to murder his brother and wreck Dragcona and Azlum on the way out, and would take part in any serious effort against Styphathal, Splynncryth or the Valley.', NULL, 'His brother Styphathal, who betrayed him; the Splugorth and their minions', 'An ancient horned dragon held in the asylum, one of the notable victims of its mysterious light. If he cannot kill Styphathal he will flee Atlantis, probably to build an empire in the Magic Zone, and return years later for revenge.', 'Rifts World Book 2: Atlantis p.30'),
('gph-the-murex-metztla', 'Gph the Murex Metztla', NULL, 'Notable asylum inmate', 'rifts', 'Murex Metztla', NULL, NULL, 'Principled (a mild mannered pacifist)', NULL, NULL, NULL, '{"ME":24,"PS":40,"PP":24,"PE":30}', NULL, NULL, 3750, NULL, 531, NULL, 17, '{"attacks":12,"initiative":2,"strike":6,"parry":10,"dodge":2,"roll":2,"pull":6}', 'His entry prints only his alignment, M.D.C., psionics and I.S.P., and calls him a typical Murex otherwise: the attributes, Horror Factor and combat figures stored are the Murex''s fixed ones (its other attributes are dice). Main body 3750; every other location is 25% below the Murex''s.', NULL, NULL, 'Standard for the Murex.', NULL, 'All the usual Murex powers, still growing with experience, plus group mind block, bio-regeneration, bio-manipulation and pyrokinesis; 531 I.S.P.', NULL, NULL, NULL, NULL, 'Loves all life and longs to help; wanders one prison-like block comforting the other inmates. Will not help an escape, which he thinks too dangerous, unless a mass breakout frees everyone; will join virtuous adventurers only if all the inmates go free.', NULL, NULL, 'A Murex made gentle by the asylum''s mysterious light, which reshaped the minds of its victims. Pronounced Giff.', 'Rifts World Book 2: Atlantis p.30'),
('pluu-and-plax', 'Pluu and Plax', NULL, 'Notable asylum inmates (a pair)', 'rifts', 'Murvoma Metztla (printed as Murma)', NULL, NULL, 'Scrupulous (both)', NULL, NULL, NULL, '{"ME":22,"PS":30,"PP":23,"PE":24}', NULL, NULL, 300, NULL, 211, NULL, 14, '{"attacks":6,"initiative":2,"strike":6,"parry":6,"dodge":4,"roll":2,"pull":4}', 'One row for two brothers, as the book prints them: one identical block. Otherwise standard for the species, so the attributes, Horror Factor and combat figures stored are the Murvoma''s fixed ones. Main body 300, mouth tentacles 45 each, octopus tentacles 60 each; other locations 25% below the species.', NULL, NULL, 'Standard for the species.', NULL, 'All the usual Murvoma powers, still growing with experience, plus psi-sword, psi-shield, hypnotic suggestion and mentally possess others at 5th level strength; 211 I.S.P. each.', NULL, NULL, NULL, NULL, 'Hatch-brothers who hate captivity and dream of escape. Held apart in isolation in maximum security for thirty years, they are thought very dangerous for their good alignments and their possession and psi-sword powers.', NULL, NULL, 'Two of five Murvoma from one hatching who were exposed to the asylum''s light at different times yet gained the same powers, and are kept for study; the other three have died, two trying to escape.', 'Rifts World Book 2: Atlantis p.30'),
('narga-the-terrible', 'Narga the Terrible', NULL, 'Reigning champion of the Alvurron arena (three years in dragon wrestling)', 'rifts', 'Thunder Lizard (ancient dragon), female', '12th level spell caster, 3rd level shifter, 10th level assassin/warrior', 12, 'Aberrant', NULL, NULL, NULL, '{"IQ":22,"ME":20,"MA":24,"PS":30,"PP":26,"PE":24,"PB":19,"Spd":23}', NULL, NULL, NULL, 700, NULL, NULL, NULL, NULL, 'Her entry prints only her levels, alignment, P.P.E. and attributes: no M.D.C., Horror Factor, attacks or combat bonuses.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Techno-wizard vampire weapons, a TW particle beam rifle, a TW bow with every kind of arrow, two TK-Gliders, a JA-9 laser rifle, an NG-P7 particle beam rifle, a C-404 SAMAS rail gun, a C-18 laser pistol, a C-27 heavy plasma cannon, two suits of heavy Dead Boy armor, a neural mace, and many vibro-blades and ordinary weapons. Rune weapons: a lesser rune dagger, a greater rune mace with air elemental magic, a crystal fire rod, Enslaver and a Sword of Atlantis.', NULL, 'Takes on every challenger in almost any kind of combat, magical or physical.', 'Bodyguards Cynthia Hartman (7th level T-Monster woman) and Ivor Shultz (8th level RPA elite in Triax X-1000 Ulti-Max armor); her best friend Myrrlux, a Volute Metztla (printed Volate)', 'Contenders for her title: Sly the Slaver and Stone-Death, a gargoyle lord', 'An ancient dragon who has held the Alvurron arena''s dragon-wrestling crown for three years, keeping a hoard of Coalition, techno-wizard and rune weapons.', 'Rifts World Book 2: Atlantis p.27'),
('lord-ahziree-aerihza', 'Lord Ahziree Aerihza', NULL, 'Lord and Clan Elder of the Aerihman clan; Atlantean Alchemist', 'rifts', 'True Atlantean', '11th level Atlantean Alchemist and Tattoo Master (special NPC); skills equal to an 11th level assassin, 6th level scientist, 5th level line walker, 2nd level techno-wizard and 2nd level stone master, all frozen', 11, 'Miscreant', '287 (looks 30)', '6 ft 7 in (1.95 m)', '190 lbs (85.5 kg)', '{"IQ":20,"ME":28,"MA":25,"PS":21,"PP":15,"PE":20,"PB":17,"Spd":22}', 57, 97, NULL, 268, 90, NULL, 11, '{"attacks":7,"strike":4,"parry":5,"dodge":4,"roll":6,"pull":6,"damage":8}', 'Hand to Hand: Assassin. +1 to strike with a body block. Critical strike on 19-20, knockout/stun on a natural 17-20, pin on 18-20. +7 vs psionics, +7 vs Horror Factor; trust/intimidate 84%, charm/impress 35%. His armor is a Sunaj assassin suit of 110 M.D.C. P.P.E. is special to the Atlantean Alchemist.', '[{"name":"Detect Ambush","pct":98},{"name":"Intelligence","pct":98},{"name":"Palming","pct":98},{"name":"Concealment","pct":96},{"name":"Forgery","pct":98},{"name":"Escape Artist","pct":98},{"name":"Swimming","pct":98},{"name":"SCUBA","pct":98},{"name":"Language: Dragonese/Elf","pct":98},{"name":"Literacy: Dragonese/Elf","pct":98},{"name":"Language: Gobblely","pct":98},{"name":"Literacy: Gobblely","pct":98},{"name":"Language: American","pct":98},{"name":"Literacy: American","pct":98},{"name":"Language: Spanish","pct":98},{"name":"Literacy: Spanish","pct":98},{"name":"Language: Euro","pct":98},{"name":"Literacy: Euro","pct":98},{"name":"Language: Atlantean","pct":98},{"name":"Literacy: Atlantean","pct":98},{"name":"Dance","pct":98},{"name":"Mathematics: Basic","pct":98},{"name":"Mathematics: Advanced","pct":98},{"name":"Chemistry","pct":98},{"name":"Chemistry: Analytical","pct":98},{"name":"Computer Operation","pct":98},{"name":"Radio: Basic","pct":98},{"name":"Radio: Scrambler","pct":98},{"name":"Basic Electronics","pct":70},{"name":"Astronomy","pct":70},{"name":"Archaeology","pct":70},{"name":"Lore: Demons & Monsters","pct":70},{"name":"Holistic Medicine","pct":70}]', 'Boxing; W.P. blunt, sword, automatic pistol, energy pistol and energy rifle. Languages and literacy at 98% as printed. Magic knowledge: making magic tattoos and the art of tattooing, with a basic grasp of stone magic, pyramid technology, techno-wizardry and line walker spell casting.', 'All the abilities common to True Atlanteans, plus an alchemist''s powers.', 'Six tattoos: the two Marks of Heritage, heart in chains (invulnerability), three lightning bolts (shoots lightning), shark (breathe without air) and a dragondactyl (a 240 M.D.C. monster).', 'I.S.P. 90; no powers are listed.', NULL, NULL, 'A TK-machinegun, a Wilk''s laser pistol converted to a techno-wizard energy system, two TW rain flares, two TW globe of daylight flares, a particle beam rifle, a silver dagger and a 9 mm Model P5 Walther (2D6 S.D.C.); often wears TW mystic power armor disguised as Sunaj armor. Can draw on any techno-wizard device or vehicle of the new Atlantean empire.', 'The wealth of the Aerihman clan.', 'Arrogant, confident, power-hungry, imaginative, deceitful and calm under pressure; a ruthless strategist who never takes reckless chances, uses betrayal freely, spares his own people, and will retreat to fight another day.', 'The Aerihman clan and its Sunaj; the Splugorth. Usually guarded by four 8th level Sunaj assassins, a 7th level ogre T-Monster Man, and his advisors Iklem (13th level stone master) and Azyyn (10th level mind melter).', 'Every other True Atlantean clan, which he means to exterminate', 'The young, adored leader of the Aerihman clan, who allied with the Splugorth to wipe out the other True Atlanteans in secret and build a new Atlantean empire. He tours the dimensions scouting battlefields, sometimes disguised as a Sunaj warrior.', 'Rifts World Book 2: Atlantis p.67');
