-- Rifts World Book 2: Atlantis - its creatures, constructs and notable NPCs.
-- 35 creatures (migration 074), 7 notable NPCs (migration 072) and their printed
-- attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-atlantis-creatures-and-npcs.sql
--
-- WHAT IS HERE:
--   * 19 beings with a stat block and no player option (playable 0): the average
--     Splugorth, High Lord and Slaver; the Murex, Volute and Murvolva Metztla and
--     the Kreelong and Kreewarr carapace drones; the Dragonsaurus, Yll Tree
--     Climber and Yazhing Multipede; the Eyes of Eylor, the Eylor Floating Eye
--     and Seeker-Hunter Eye; and five rune statues (dragon head, dragon,
--     gargoyle, fire-breathing lion, combat/guardian);
--   * the 16 playable races as their NPC view (playable 1). They are also
--     published classes and their slugs are the class ids. The three Kittani
--     R.C.C.s share the race's stats and differ in skills_note. Shaydor Spherian
--     is not here: South America's script already holds it;
--   * 7 named beings with a stat block: Splynncryth, Styphathal, Stydro, Gph,
--     Pluu and Plax (one row, as the book prints them), Narga the Terrible and
--     Lord Ahziree Aerihza.
--
-- ALL ARE NEW: no slug existed in production on 2026-09-26.
--
-- A RIFTS BOOK: an M.D.C. being's pool is its main-body M.D.C.; M.D.C. by
-- location, per-level growth and any figure the roll grammar cannot take are in
-- pools_note. The book is a scan: the OCR drops the x from dice (1D610 is
-- 1D6x10) and merges S into digits; figures in doubt were read off a render.
-- Every creature row passes creatureFormulaGaps (js/creature-roll.js), the
-- grammar the "roll creatures" endpoint uses. ONLY PRINTED ATTACKS: a being
-- whose damage "varies with P.S." (the average Splugorth) carries none, and so
-- do Narga, Stydro, Gph and Pluu and Plax, whose entries print none. Prose
-- fields are short paraphrases: an 8-word shingle check against the cache
-- finds none in any description, disposition or note sentence. What it still
-- matches is lists of names and figures the book prints - skills, psionic
-- powers, spells, gear, and M.D.C. by location.
--
-- JUDGEMENT CALLS, each on its page: the Eyes of Eylor store the small eye
-- (M.D.C. 40, P.P.E. 150) with the size ladder in pools_note, and take Spd 50
-- from printed 124; the floating and seeker eyes store the eye's M.D.C. with the
-- sphere's in pools_note (124); the rune statues are indestructible, so carry no
-- M.D.C., and the dragon head stores the minimum P.S. 20 and P.P. 18 every rune
-- statue has (132); the Slaver's 120 M.D.C. is its always-ready Armor of Ithan
-- (49); the Yazhing stores the common small animal, giants in notes and
-- attacks, and leaves out the size sentence the book repeats from the Yll
-- entry (81); Gph and Pluu and Plax carry their species' fixed attributes,
-- Horror Factor and combat, their entries calling them typical of it (30);
-- the book's "Murma" is read as the Murvoma (30); the Adarok stores the stat
-- block's P.P.E. 2D4x10+45 over the magic line's +40 (69), the Murvoma its stat
-- block's 1D6x10 over the magic line's 1D4x10 (58, 60).









-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 35 Atlantis creatures are in' AS assertion, count(*) AS got, 35 AS want
  FROM creatures WHERE slug IN ('splugorth', 'splugorth-high-lord', 'splugorth-slaver', 'murex-metztla', 'volute-metztla', 'murvolva-metztla', 'kreelong-carapace', 'kreewarr-carapace', 'dragonsaurus', 'yll-tree-climber', 'yazhing-multipede', 'eyes-of-eylor', 'eylor-floating-eye', 'eylor-seeker-hunter-eye', 'rune-statue-dragon-head', 'rune-statue-dragon', 'rune-statue-gargoyle', 'rune-statue-fire-breathing-lion', 'rune-statue-combat-guardian', 'true-atlantean', 'splugorth-conservator', 'splugorth-overlord', 'splugorth-powerlord', 'blind-warrior-women', 'kittani-warrior', 'kittani-field-mechanic', 'kittani-espionage', 'murvoma-metztla', 'adarok', 'erta', 'hawrk-duhk', 'hawrk-ka', 'hawrk-ohl', 'shaydor-intel', 'zembahk');
SELECT 'and 16 of them are the playable races' AS assertion, count(*) AS got, 16 AS want
  FROM creatures WHERE slug IN ('splugorth', 'splugorth-high-lord', 'splugorth-slaver', 'murex-metztla', 'volute-metztla', 'murvolva-metztla', 'kreelong-carapace', 'kreewarr-carapace', 'dragonsaurus', 'yll-tree-climber', 'yazhing-multipede', 'eyes-of-eylor', 'eylor-floating-eye', 'eylor-seeker-hunter-eye', 'rune-statue-dragon-head', 'rune-statue-dragon', 'rune-statue-gargoyle', 'rune-statue-fire-breathing-lion', 'rune-statue-combat-guardian', 'true-atlantean', 'splugorth-conservator', 'splugorth-overlord', 'splugorth-powerlord', 'blind-warrior-women', 'kittani-warrior', 'kittani-field-mechanic', 'kittani-espionage', 'murvoma-metztla', 'adarok', 'erta', 'hawrk-duhk', 'hawrk-ka', 'hawrk-ohl', 'shaydor-intel', 'zembahk') AND playable = 1;
SELECT 'all 7 notable NPCs are in' AS assertion, count(*) AS got, 7 AS want
  FROM notable_npcs WHERE slug IN ('splynncryth', 'styphathal', 'stydro', 'gph-the-murex-metztla', 'pluu-and-plax', 'narga-the-terrible', 'lord-ahziree-aerihza');
SELECT 'the creatures carry 170 attacks' AS assertion, count(*) AS got, 170 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('splugorth', 'splugorth-high-lord', 'splugorth-slaver', 'murex-metztla', 'volute-metztla', 'murvolva-metztla', 'kreelong-carapace', 'kreewarr-carapace', 'dragonsaurus', 'yll-tree-climber', 'yazhing-multipede', 'eyes-of-eylor', 'eylor-floating-eye', 'eylor-seeker-hunter-eye', 'rune-statue-dragon-head', 'rune-statue-dragon', 'rune-statue-gargoyle', 'rune-statue-fire-breathing-lion', 'rune-statue-combat-guardian', 'true-atlantean', 'splugorth-conservator', 'splugorth-overlord', 'splugorth-powerlord', 'blind-warrior-women', 'kittani-warrior', 'kittani-field-mechanic', 'kittani-espionage', 'murvoma-metztla', 'adarok', 'erta', 'hawrk-duhk', 'hawrk-ka', 'hawrk-ohl', 'shaydor-intel', 'zembahk');
SELECT 'and the notables 9' AS assertion, count(*) AS got, 9 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('splynncryth', 'styphathal', 'stydro', 'gph-the-murex-metztla', 'pluu-and-plax', 'narga-the-terrible', 'lord-ahziree-aerihza');

-- Records this run. See db/migrations/024-data-script-runs.sql.
